package com.smartroad.services.core.dto.tracking;

import com.fasterxml.jackson.annotation.JsonInclude;
import com.smartroad.services.core.dto.shift.ShiftAttendanceInfoDTO;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.OffsetDateTime;
import java.util.List;
import java.util.UUID;

/**
 * Request and response shapes for attendance check-in, check-out and the daily summaries.
 * Every timestamp is generated by the server; clients never supply one.
 */
public class AttendanceDTO {

    private AttendanceDTO() {
    }

    /**
     * Where the check-in or check-out happened, supplied by the client for the record only.
     *
     * @param latitude the latitude, or null
     * @param longitude the longitude, or null
     * @param accuracy the position accuracy in metres, or null
     */
    public record Position(BigDecimal latitude, BigDecimal longitude, BigDecimal accuracy) {}

    /**
     * Outcome of a check-in or check-out. The check-out fields are absent for a check-in.
     *
     * @param workerId the worker UUID
     * @param employeeId the worker's employee ID, e.g. SR1
     * @param workerName the worker's display name
     * @param attendanceDate the date of the session, from the server clock
     * @param checkInTime the server time of the check-in
     * @param checkOutTime the server time of the check-out, present only after check-out
     * @param checkInMethod how the worker checked in: QR, FACE or MANUAL
     * @param checkOutMethod how the worker checked out, present only after check-out
     * @param workDuration the length of this session as HH:mm:ss, present only after check-out
     * @param status CHECKED_IN or CHECKED_OUT
     */
    @JsonInclude(JsonInclude.Include.NON_NULL)
    public record EventResponse(UUID workerId, String employeeId, String workerName, LocalDate attendanceDate,
                                OffsetDateTime checkInTime, OffsetDateTime checkOutTime, String checkInMethod,
                                String checkOutMethod, String workDuration, String status) {}

    /**
     * One work session inside a day.
     *
     * @param id the session UUID
     * @param projectId the project the session belongs to
     * @param checkInTime the server time of the check-in
     * @param checkOutTime the server time of the check-out, null while the session is open
     * @param checkInMethod how the worker checked in
     * @param checkOutMethod how the worker checked out, null while the session is open
     * @param durationSeconds the session length in seconds, null while the session is open
     */
    @JsonInclude(JsonInclude.Include.NON_NULL)
    public record Session(UUID id, UUID projectId, OffsetDateTime checkInTime, OffsetDateTime checkOutTime,
                          String checkInMethod, String checkOutMethod, Long durationSeconds) {}

    /**
     * A worker's attendance for one date. First check-in and last check-out span every session of the
     * day; total work time is the sum of the closed sessions, never last check-out minus first check-in.
     *
     * @param workerId the worker UUID
     * @param employeeId the worker's employee ID
     * @param workerName the worker's display name
     * @param attendanceDate the date
     * @param firstCheckInTime the earliest check-in of the day, null when there is none
     * @param lastCheckOutTime the latest check-out of the day, null when no session is closed
     * @param totalWorkSeconds the summed length of the closed sessions
     * @param totalWorkDuration totalWorkSeconds as HH:mm:ss
     * @param status NOT_CHECKED_IN, CHECKED_IN (a session is open) or CHECKED_OUT
     * @param sessions every session of the day, earliest first
     * @param shiftInfo the worker's scheduled shift for this date and how the day compared to it,
     *                  or null when the worker holds no shift assignment covering this date. This
     *                  is an additive enrichment resolved from shift management; it never changes
     *                  how check-in/check-out sessions themselves are recorded or summed above.
     */
    @JsonInclude(JsonInclude.Include.NON_NULL)
    public record DailySummary(UUID workerId, String employeeId, String workerName, LocalDate attendanceDate,
                               OffsetDateTime firstCheckInTime, OffsetDateTime lastCheckOutTime, long totalWorkSeconds,
                               String totalWorkDuration, String status, List<Session> sessions,
                               ShiftAttendanceInfoDTO shiftInfo) {}
}
